  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] [DecidableEq ι] (i j : ι) (b : M j) :
  (DirectSum.component R ι M i) ((DirectSum.lof R ι M j) b) = if h : j = i then Eq.recOn h b else 0

theorem DirectSum.IsInternal.collectedBasis_repr_of_mem_ne.{u, v, u_1, u_2} {R : Type u} [Semiring R]
  {ι : Type v} [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommMonoid M] [Module R M]
  {A : ι → Submodule R M} (h : DirectSum.IsInternal A) {α : ι → Type u_2}
  (v : (i : ι) → Module.Basis (α i) R ↥(A i)) {x : M} {i j : ι} (hij : i ≠ j) {a : α j}
  (hx : x ∈ A i) : ((h.collectedBasis v).repr x) ⟨j, a⟩ = 0

theorem DirectSum.IsInternal.collectedBasis_coe.{u, v, u_1, u_2} {R : Type u} [Semiring R] {ι : Type v}
  [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommMonoid M] [Module R M] {A : ι → Submodule R M}
  (h : DirectSum.IsInternal A) {α : ι → Type u_2} (v : (i : ι) → Module.Basis (α i) R ↥(A i)) :
  ⇑(h.collectedBasis v) = fun a => ↑((v a.fst) a.snd)

theorem DirectSum.single_eq_lof.{u, v, w} (R : Type u) [Semiring R] {ι : Type v} {M : ι → Type w}
  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] [DecidableEq ι] (i : ι) (b : M i) :
  DFinsupp.single i b = (DirectSum.lof R ι M i) b

