fun R [Semiring R] {ι} {α} {δ} [DecidableEq ι] [(i : ι) → (j : α i) → AddCommMonoid (δ i j)]
    [(i : ι) → (j : α i) → Module R (δ i j)] =>
  let __src := DirectSum.sigmaCurry;
  { toFun := (↑__src).toFun, map_add' := ⋯, map_smul' := ⋯ }

