theorem DirectSum.lid_apply.{u, v, u_1} (R : Type u) [Semiring R] {M : Type v} {ι : Type u_1}
  [AddCommMonoid M] [Module R M] [Unique ι] (x : DirectSum ι fun x => M) :
  (DirectSum.lid R M ι) x = x default

theorem DirectSum.IsInternal.submodule_iSup_eq_top.{u, v, u_1} {R : Type u} [Semiring R] {ι : Type v}
  [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommMonoid M] [Module R M] {A : ι → Submodule R M}
  (h : DirectSum.IsInternal A) : iSup A = ⊤

def DirectSum.coeFnLinearMap.{u, v, w} (R : Type u) [Semiring R] {ι : Type v} {M : ι → Type w}
  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] :
  (DirectSum ι fun i => M i) →ₗ[R] (i : ι) → M i

theorem DirectSum.linearMap_ext.{u, v, w, u₁} (R : Type u) [Semiring R] {ι : Type v} {M : ι → Type w}
  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] [DecidableEq ι] {N : Type u₁}
  [AddCommMonoid N] [Module R N] ⦃ψ ψ' : (DirectSum ι fun i => M i) →ₗ[R] N⦄
  (H : ∀ (i : ι), ψ ∘ₗ DirectSum.lof R ι M i = ψ' ∘ₗ DirectSum.lof R ι M i) : ψ = ψ'

theorem DirectSum.lmap_surjective.{u, v, w, u_1} {R : Type u} [Semiring R] {ι : Type v} {M : ι → Type w}
  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] {N : ι → Type u_1}
  [(i : ι) → AddCommMonoid (N i)] [(i : ι) → Module R (N i)] (f : (i : ι) → M i →ₗ[R] N i) :
  Function.Surjective ⇑(DirectSum.lmap f) ↔ ∀ (i : ι), Function.Surjective ⇑(f i)

theorem DirectSum.IsInternal.submodule_iSupIndep.{u, v, u_1} {R : Type u} [Semiring R] {ι : Type v}
  [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommMonoid M] [Module R M] {A : ι → Submodule R M}
  (h : DirectSum.IsInternal A) : iSupIndep A

theorem DirectSum.IsInternal.collectedBasis_mem.{u, v, u_1, u_2} {R : Type u} [Semiring R] {ι : Type v}
  [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommMonoid M] [Module R M] {A : ι → Submodule R M}
  (h : DirectSum.IsInternal A) {α : ι → Type u_2} (v : (i : ι) → Module.Basis (α i) R ↥(A i))
  (a : (i : ι) × α i) : (h.collectedBasis v) a ∈ A a.fst

theorem DirectSum.toModule_lof.{u, v, w, u₁} (R : Type u) [Semiring R] {ι : Type v} {M : ι → Type w}
  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] [DecidableEq ι] {N : Type u₁}
  [AddCommMonoid N] [Module R N] {φ : (i : ι) → M i →ₗ[R] N} (i : ι) (x : M i) :
  (DirectSum.toModule R ι N φ) ((DirectSum.lof R ι M i) x) = (φ i) x

theorem DirectSum.isInternal_ne_bot_iff.{u, v, u_1} {R : Type u} [Ring R] {ι : Type v}
  [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommGroup M] [Module R M] {A : ι → Submodule R M} :
  (DirectSum.IsInternal fun i => A ↑i) ↔ DirectSum.IsInternal A

theorem DirectSum.IsInternal.isCompl.{u, v, u_1} {R : Type u} [Semiring R] {ι : Type v}
  [dec_ι : DecidableEq ι] {M : Type u_1} [AddCommMonoid M] [Module R M] {A : ι → Submodule R M}
  {i j : ι} (hij : i ≠ j) (h : Set.univ = {i, j}) (hi : DirectSum.IsInternal A) :
  IsCompl (A i) (A j)

def DirectSum.lequivCongrLeft.{u, v, w, u_1} (R : Type u) [Semiring R] {ι : Type v} {M : ι → Type w}
  [(i : ι) → AddCommMonoid (M i)] [(i : ι) → Module R (M i)] {κ : Type u_1} (h : ι ≃ κ) :
  (DirectSum ι fun i => M i) ≃ₗ[R] DirectSum κ fun k => M (h.symm k)
